-- Development feature migration after V209. Publishes a new account profile configuration.
-- Existing business values, old configurations, draft configurations and submission history are retained.
-- New pc_* fields start empty; no historical business meaning is inferred or backfilled.
-- Re-run is guarded by V210. Rollback requires selecting a previous config, retaining history.
-- No role grants. New material filters are populated only from existing dictionary values below.
DROP PROCEDURE IF EXISTS zsjos_V210_positioning;
DELIMITER $$
CREATE PROCEDURE zsjos_V210_positioning()
BEGIN
 DECLARE done INT DEFAULT 0;
 DECLARE cid BIGINT;
 DECLARE tid BIGINT;
 DECLARE version_number INT;
 DECLARE old_fields JSON;
 DECLARE added JSON;
 DECLARE merged JSON;
 DECLARE idx INT;
 DECLARE total_fields INT;
 DECLARE item JSON;
 DECLARE code_value VARCHAR(100);
 DECLARE cursor_configs CURSOR FOR SELECT id,tenant_id,fields_json FROM zsjos_media_account_field_config WHERE status='published' AND deleted=b'0';
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=1;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF NOT EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V210') THEN
 START TRANSACTION;
 SET added=CAST('[{"key":"pc_account_name","label":"账号名称建议","description":"注意描述：最好帮助运营直接定下来","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":10,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_account_position","label":"账号定位","description":"选择账号人设类型","type":"multi_select","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":20,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","dictType":"zsjos_persona_type"},{"key":"pc_profession","label":"专业定位","description":"选择素材适配专业方向","type":"multi_select","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":30,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","dictType":"zsjos_material_profession"},{"key":"pc_target_user","label":"目标用户","description":"","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":40,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_content_form","label":"主要内容形式","description":"从管理员维护的选项中选择，可多选","type":"multi_select","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":50,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","dictType":"zsjos_director_content_form"},{"key":"pc_lead_capture","label":"客资提取方式","description":"","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":60,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_product_goal","label":"承接产品目标","description":"","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":70,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_join_goal","label":"学员加入目标","description":"兼职变现、新媒体能力成长、职业转型、IP打造、业务增量等","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":80,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_learning_stage","label":"当前学习/资格阶段","description":"未报名/在学/备考/持证/从业/成熟服务者","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":90,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_primary_track","label":"主赛道","description":"营养/心理/中医适宜技术/药师/健康管理/慢病/其他","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":100,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_secondary_track","label":"辅赛道","description":"最多1项；说明为什么对主用户有帮助","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":110,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_cooperation","label":"学员配合等级","description":"A级（每周8小时以上）、B级（每周4-8小时）、C级（每周不足4小时）","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":120,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_shoot_time","label":"连续可拍摄时间","description":"有半天/一天连续时间，或仅碎片化时段","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":130,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_appearance","label":"出镜意愿","description":"愿意出镜、条件式出镜、完全不出镜","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":140,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_expression","label":"表达能力等级","description":"自然表达、提词表达、采访表达、表达较弱","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":150,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_assets","label":"专业优势和案例资产","description":"证书、技能、职业经历、可拍素材（学习笔记/实操场景/案例截图等）","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":160,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_trust","label":"信任证据","description":"学习过程、职业经历、工具、案例、资质、老师授权（可查看）","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":170,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_risk","label":"执行主要风险","description":"时间不足/出镜顾虑/合规表达习惯/熟人可见/断更等","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":180,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_history","label":"历史定位、采访记录","description":"查看系统实际保存的记录","type":"text","ownerType":"AUTO","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":190,"searchable":false,"sourceType":"PENDING","snapshotPolicy":"ON_SELECTION"},{"key":"pc_days7","label":"7天账号数据","description":"测试账号是否正常、数据是否正常","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":200,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_days14","label":"14天验证指标","description":"发布、互动、咨询和执行指标及复核日期","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":210,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_days28","label":"28天调整触发条件","description":"何时改选题、形式、类型或人群","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":220,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_student_duties","label":"学员承担事项","description":"拍摄/制作/发布/评论承接/私信回复/客资登记提交等","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":230,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_company_duties","label":"公司承担事项","description":"选题/脚本/模板/素材/剪辑支持/辅导/数据复盘等","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":240,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_homepage_douyin","label":"抖音平台主页搭建","description":"主页搭建、头像选择、背景图设置、主页引导语设置、置顶视频描述等建议（暂时不做改平台账号，暂时不做）","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":250,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_homepage_douyin_refs","label":"抖音平台主页搭建参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":251,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_homepage_douyin","materialTypeCode":"viral_account","recommendedCount":"1-3"},{"key":"pc_homepage_xiaohongshu","label":"小红书平台主页搭建","description":"主页搭建、头像选择、背景图设置、主页引导语设置、置顶视频描述等建议（暂时不做改平台账号，暂时不做）","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":260,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_homepage_xiaohongshu_refs","label":"小红书平台主页搭建参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":261,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_homepage_xiaohongshu","materialTypeCode":"viral_account","recommendedCount":"1-3"},{"key":"pc_homepage_channels","label":"视频号平台主页搭建","description":"主页搭建、头像选择、背景图设置、主页引导语设置、置顶视频描述等建议（暂时不做改平台账号，暂时不做）","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":270,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_homepage_channels_refs","label":"视频号平台主页搭建参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":271,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_homepage_channels","materialTypeCode":"viral_account","recommendedCount":"1-3"},{"key":"pc_homepage_other","label":"其他平台主页搭建","description":"主页搭建、头像选择、背景图设置、主页引导语设置、置顶视频描述等建议（暂时不做改平台账号，暂时不做）","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":280,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_homepage_other_refs","label":"其他平台主页搭建参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":281,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_homepage_other","materialTypeCode":"viral_account","recommendedCount":"1-3"},{"key":"pc_delivery_s0","label":"S0期交付约定","description":"明确交付形式、交付数量、交付频次、交付内容、客资结果；学员需要学习的内容目标、结果目标","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":290,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_delivery_s1","label":"S1期交付约定","description":"明确交付形式、交付数量、交付频次、交付内容、客资结果；学员需要学习的内容目标、结果目标","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":300,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_delivery_s1_refs","label":"S1期交付约定参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":301,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_delivery_s1","materialTypeCode":"viral_content","recommendedCount":"2-4"},{"key":"pc_delivery_s2","label":"S2期交付约定","description":"明确交付形式、交付数量、交付频次、交付内容、客资结果；学员需要学习的内容目标、结果目标","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":310,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_delivery_s2_refs","label":"S2期交付约定参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":311,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_delivery_s2","materialTypeCode":"viral_content","recommendedCount":"2-4"},{"key":"pc_delivery_s3","label":"S3期交付约定","description":"明确交付形式、交付数量、交付频次、交付内容、客资结果；学员需要学习的内容目标、结果目标","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":320,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_delivery_s3_refs","label":"S3期交付约定参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":321,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_delivery_s3","materialTypeCode":"viral_content","recommendedCount":"4-6"},{"key":"pc_delivery_s4","label":"S4期交付约定","description":"明确交付形式、交付数量、交付频次、交付内容、客资结果；学员需要学习的内容目标、结果目标","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":330,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_delivery_s4_refs","label":"S4期交付约定参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":331,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_delivery_s4","materialTypeCode":"viral_content","recommendedCount":"4-7"},{"key":"pc_delivery_s5","label":"S5期交付约定","description":"明确交付形式、交付数量、交付频次、交付内容、客资结果；学员需要学习的内容目标、结果目标","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":340,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_delivery_s5_refs","label":"S5期交付约定参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":341,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_delivery_s5","materialTypeCode":"viral_content","recommendedCount":"4-8"},{"key":"pc_delivery_s6","label":"S6期交付约定","description":"明确交付形式、交付数量、交付频次、交付内容、客资结果；学员需要学习的内容目标、结果目标","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":350,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_delivery_s6_refs","label":"S6期交付约定参考素材","description":"","type":"materials","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":351,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION","referenceFor":"pc_delivery_s6","materialTypeCode":"viral_content","recommendedCount":"6-9"},{"key":"pc_internal_goal","label":"内部交付目标建议","description":"A级：每月50-100条；B级：每月30-60条；C级：先完成账号运行与能力培养","type":"textarea","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":360,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"},{"key":"pc_interview_files","label":"采访稿全文","description":"上传本次文稿附件","type":"attachment","ownerType":"DIRECTOR","group":"POSITIONING","required":false,"requiredForCreate":false,"requiredForComplete":false,"enabled":true,"sort":370,"searchable":false,"sourceType":"MANUAL","snapshotPolicy":"ON_SELECTION"}]' AS JSON);
 SET idx=0;
 WHILE idx<JSON_LENGTH(added) DO
  SET item=JSON_EXTRACT(added,CONCAT('$[',idx,']'));
  SET code_value=NULL;
  IF JSON_UNQUOTE(JSON_EXTRACT(item,'$.materialTypeCode'))='viral_account' THEN
   SELECT MIN(value) INTO code_value FROM system_dict_data WHERE dict_type='zsjos_account_platform' AND deleted=b'0' AND status=0
    AND label=CASE JSON_UNQUOTE(JSON_EXTRACT(item,'$.referenceFor')) WHEN 'pc_homepage_douyin' THEN '抖音' WHEN 'pc_homepage_xiaohongshu' THEN '小红书' WHEN 'pc_homepage_channels' THEN '视频号' ELSE '其他' END;
   IF code_value IS NOT NULL THEN SET added=JSON_SET(added,CONCAT('$[',idx,'].defaultPlatform'),code_value); END IF;
  ELSEIF JSON_UNQUOTE(JSON_EXTRACT(item,'$.materialTypeCode'))='viral_content' THEN
   SELECT MIN(value) INTO code_value FROM system_dict_data WHERE dict_type='zsjos_media_account_stage' AND deleted=b'0' AND status=0
    AND UPPER(value)=UPPER(RIGHT(JSON_UNQUOTE(JSON_EXTRACT(item,'$.referenceFor')),2));
   IF code_value IS NOT NULL THEN SET added=JSON_SET(added,CONCAT('$[',idx,'].defaultAccountStage'),code_value); END IF;
  END IF;
  SET idx=idx+1;
 END WHILE;
 OPEN cursor_configs;
 config_loop: LOOP
 FETCH cursor_configs INTO cid,tid,old_fields;
  IF done=1 THEN LEAVE config_loop; END IF;
  -- A tenant-customized baseline is left untouched; only the known V209 shape is upgraded.
  IF NOT JSON_CONTAINS(old_fields,CAST('{"key":"account_position","label":"账号定位","type":"text"}' AS JSON))
     OR NOT JSON_CONTAINS(old_fields,CAST('{"key":"professional_position","label":"专业定位","type":"text"}' AS JSON))
     OR NOT JSON_CONTAINS(old_fields,CAST('{"key":"content_format","label":"内容主要形式","type":"select"}' AS JSON))
     OR NOT JSON_CONTAINS(old_fields,CAST('{"key":"positioning_history","label":"历史定位与采访记录","type":"record"}' AS JSON)) THEN
    ITERATE config_loop;
  END IF;
  SET merged=JSON_ARRAY(); SET idx=0; SET total_fields=JSON_LENGTH(old_fields);
  WHILE idx<total_fields DO
   SET item=JSON_EXTRACT(old_fields,CONCAT('$[',idx,']'));
   IF JSON_UNQUOTE(JSON_EXTRACT(item,'$.group'))='POSITIONING' THEN SET item=JSON_SET(item,'$.enabled',FALSE); END IF;
   SET merged=JSON_ARRAY_APPEND(merged,'$',item); SET idx=idx+1;
  END WHILE;
  SET merged=JSON_MERGE_PRESERVE(merged,added);
  SELECT COALESCE(MAX(version_no),0)+1 INTO version_number FROM zsjos_media_account_field_config WHERE tenant_id=tid;
  UPDATE zsjos_media_account_field_config SET status='archived' WHERE id=cid;
